state_machine InstrumentControl {
  // External telescope state must remain TELESCOPE_OP during all transitions
  guard telescope_state == TELESCOPE_OP;

  // States
  state SRS_IDLE {
    on START -> SRS_STARTING { action: send START_ACK; }
    on SELF_TEST -> error SRS_ERR_INVALID_STATE;
    on CONFIGURE -> error SRS_ERR_INVALID_STATE;
    on DYNAMIC_RECONFIG -> error SRS_ERR_INVALID_STATE;
    on SHUTDOWN -> error SRS_ERR_INVALID_STATE;
  }
  state SRS_STARTING {
    on START_ACK -> SRS_RUNNING;
  }
  state SRS_RUNNING {
    on SHUTDOWN -> SRS_SHUTTING_DOWN;
    on SELF_TEST -> SRS_SELF_TESTING;
    on CONFIGURE -> SRS_CONFIGURING;
    on DYNAMIC_RECONFIG -> SRS_RUNNING; // no state change
  }
  state SRS_SHUTTING_DOWN {
    on SHUTDOWN_ACK -> SRS_IDLE;
  }
  state SRS_SELF_TESTING {
    on SELF_TEST_ACK -> SRS_RUNNING;
  }
  state SRS_CONFIGURING {
    on CONFIGURE_ACK -> SRS_RUNNING;
  }
  // Continuous status monitoring
  on STATUS_UPDATE(subsystem, status) -> SRS_RUNNING { action: update_status(subsystem, status); }

  // Error handling
  on UNKNOWN_CMD -> error SRS_ERR_UNKNOWN_CMD;
}
